sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var method = request.httpMethod;
    try {
        var body;
        if (method === 'GET') {
            body = getList(request.queryParams);
        } else if (method === 'POST') {
            body = createIssue(request.body.data);
        } else {
            response.setStatus(405);
            return { success: false, error: 'Method not allowed' };
        }
        response.setStatus(body.success ? 200 : 400);
        return body;
    } catch (e) {
        response.setStatus(500);
        return { success: false, error: e.message };
    }

    function getList(qp) {
        var gr = new GlideRecord('x_2145749_qc_store_issue');
        if (qp.store) gr.addQuery('dark_store', qp.store);
        if (qp.state) gr.addQuery('state', qp.state);
        gr.orderByDesc('sys_created_on');
        var limit = parseInt(qp.limit, 10) || 50;
        var offset = parseInt(qp.offset, 10) || 0;
        gr.chooseWindow(offset, offset + limit);
        gr.query();
        var results = [];
        while (gr.next()) {
            results.push(toObj(gr));
        }
        return { success: true, result: results };
    }

    function createIssue(data) {
        if (!data || !data.store || !data.issue_category) {
            return { success: false, error: 'store and issue_category are required' };
        }
        var gr = new GlideRecord('x_2145749_qc_store_issue');
        gr.initialize();
        gr.dark_store = data.store;
        gr.issue_category = data.issue_category;
        gr.description = data.description || '';
        gr.state = 'open';
        gr.affects_pulse_score = true;
        var sysId = gr.insert();
        if (!sysId) {
            return { success: false, error: 'Insert failed' };
        }
        gr.get(sysId);
        return { success: true, result: toObj(gr) };
    }

    function toObj(gr) {
        return {
            sys_id: gr.getUniqueValue(),
            store: gr.dark_store.getDisplayValue(),
            issue_category: gr.issue_category.toString(),
            description: gr.description.toString(),
            state: gr.state.toString(),
            severity: gr.severity.toString(),
            created: gr.sys_created_on.toString()
        };
    }
})(request, response);
